"""Integration test: v2 pipeline recall on the 300-item hand-labelled golden dataset.

Requires a live LLM API key (ANTHROPIC_SENIOR_DEVELOPER_KEY or GEMINI_SENIOR_DEVELOPER_KEY).
Skipped automatically in CI / environments without a key.

Target: recall >= 14/17 YES jobs, 0 false positives on NO jobs.
"""

from __future__ import annotations

import json
import os
from pathlib import Path

import pytest

GOLDEN = Path(__file__).resolve().parent / "golden-dataset"
JOBS_PATH = GOLDEN / "jobs.jsonl"
LABELLED_PATH = GOLDEN / "labelled_300.jsonl"
SEARCH_INPUTS = GOLDEN / "user_search_inputs"

_has_llm_key = bool(
    os.environ.get("ANTHROPIC_SENIOR_DEVELOPER_KEY")
    or os.environ.get("GEMINI_SENIOR_DEVELOPER_KEY")
    or (
        Path(".env").exists()
        and any(
            k in Path(".env").read_text()
            for k in ("ANTHROPIC_SENIOR_DEVELOPER_KEY", "GEMINI_SENIOR_DEVELOPER_KEY")
        )
    )
)
_requires_llm = pytest.mark.skipif(not _has_llm_key, reason="No LLM API key — set ANTHROPIC_SENIOR_DEVELOPER_KEY")


# ---------------------------------------------------------------------------
# Dataset sanity checks (no pipeline needed)
# ---------------------------------------------------------------------------


@pytest.fixture(scope="module")
def labelled_rows():
    return [json.loads(l) for l in LABELLED_PATH.read_text(encoding="utf-8").splitlines() if l.strip()]


def test_labelled_dataset_has_expected_shape(labelled_rows):
    assert len(labelled_rows) == 300
    for row in labelled_rows:
        assert "job_id" in row
        assert row["decision"] in ("yes", "no")
        assert "reason" in row


def test_labelled_yes_jobs_count(labelled_rows):
    yes = [r for r in labelled_rows if r["decision"] == "yes"]
    assert len(yes) == 17


def test_labelled_no_jobs_include_dead_links(labelled_rows):
    dead_nos = [r for r in labelled_rows if r["decision"] == "no" and "404/410" in r.get("reason", "")]
    assert len(dead_nos) >= 29


# ---------------------------------------------------------------------------
# Pipeline fixtures
# ---------------------------------------------------------------------------


@_requires_llm
